+package network
+
+import (
+	"errors"
+	"fmt"
+	"math/rand"
+	"net"
+	"os"
+	"time"
+
+	"code.cloudfoundry.org/guardian/kawasaki/netns"
+	"github.com/vishvananda/netlink"
+)
+
+const (
+	BridgeName    = "worker"
+	BridgeCIDR    = "172.29.0.1/16"
+	WaitTimeout   = time.Minute * 3
+	CheckInterval = time.Millisecond * 500
+)
+
+//ErrInterfaceTimeOut is returned by a child process when its veth pair is not ready after MaxWait
+var ErrInterfaceTimedOut = errors.New("timed out waiting for child veth")
+
+//Initialize creates the worker bridge on the host if necessary and a virtual ethernet pair
+//for the child. The child veth link then gets assigned an ip address and a route to the bridge.
+func Initialize(identifier string, pid int) error {
+	childLink, err := createNetworkDevices(identifier, pid)
+	if err != nil {
+		return err
+	}
+
+	if err := setupNetwork(childLink, pid); err != nil {
+		return err
+	}
+
+	return nil
+}
+
+func createNetworkDevices(identifier string, pid int) (netlink.Link, error) {
+	bridge, err := createBridge(BridgeName, BridgeCIDR)
+	if err != nil {
+		return nil, err
+	}
+
+	hostVeth, childVeth, err := createVeth(identifier)
+	if err != nil {
+		return nil, err
+	}
+
+	bridgeLink, err := netlink.LinkByName(bridge.Name)
+	if err != nil {
+		return nil, err
+	}
+
+	hostVethLink, err := netlink.LinkByName(hostVeth.Name)
+	if err != nil {
+		return nil, err
+	}
+
+	if err := netlink.LinkSetMaster(hostVethLink, bridgeLink); err != nil {
+		return nil, err
+	}
+
+	childVethLink, err := netlink.LinkByName(childVeth.Name)
+	if err != nil {
+		return nil, err
+	}
+
+	if err := netlink.LinkSetNsPid(childVethLink, pid); err != nil {
+		return nil, err
+	}
+
+	return childVethLink, nil
+}
+
+func createBridge(name, cidr string) (*net.Interface, error) {
+	iface, err := net.InterfaceByName(name)
+	if err == nil {
+		return iface, nil
+	}
+
+	link := &netlink.Bridge{LinkAttrs: netlink.LinkAttrs{Name: name}}
+
+	if err := netlink.LinkAdd(link); err != nil {
+		return nil, err
+	}
+
+	addr, err := netlink.ParseAddr(cidr)
+	if err != nil {
+		return nil, err
+	}
+
+	if err := netlink.AddrAdd(link, addr); err != nil {
+		return nil, err
+	}
+
+	if err := netlink.LinkSetUp(link); err != nil {
+		return nil, err
+	}
+
+	return net.InterfaceByName(name)
+}
+
+func createVeth(identifier string) (*net.Interface, *net.Interface, error) {
+	hostVeth := "veth0_" + identifier
+	childVeth := "veth1_" + identifier
+
+	hostIface, err := net.InterfaceByName(hostVeth)
+	if err == nil {
+		childIface, err := net.InterfaceByName(childVeth)
+		if err != nil {
+			return nil, nil, err
+		}
+		return hostIface, childIface, nil
+	}
+
+	veth := &netlink.Veth{
+		LinkAttrs: netlink.LinkAttrs{
+			Name:   hostVeth,
+			TxQLen: -1,
+		},
+		PeerName: childVeth,
+	}
+
+	if err := netlink.LinkAdd(veth); err != nil {
+		return nil, nil, err
+	}
+
+	if err := netlink.LinkSetUp(veth); err != nil {
+		return nil, nil, err
+	}
+
+	hostIface, err = net.InterfaceByName(hostVeth)
+	if err != nil {
+		return nil, nil, err
+	}
+
+	childIface, err := net.InterfaceByName(childVeth)
+	if err != nil {
+		return nil, nil, err
+	}
+
+	return hostIface, childIface, nil
+}
+
+func setupNetwork(link netlink.Link, pid int) error {
+	netnsFile, err := os.Open(fmt.Sprintf("/proc/%d/ns/net", pid))
+	defer netnsFile.Close()
+	if err != nil {
+		return fmt.Errorf("unable to find network namespace %w", err)
+	}
+
+	netnsExecer := &netns.Execer{}
+
+	apply := func() error {
+		address, err := netlink.ParseAddr(generateIP() + "/16")
+		if err != nil {
+			return err
+		}
+
+		addr := &netlink.Addr{IPNet: &net.IPNet{IP: address.IP, Mask: address.Mask}}
+		err = netlink.AddrAdd(link, addr)
+		if err != nil {
+			return fmt.Errorf("unable to assign IP address to child veth %w", err)
+		}
+
+		if err := netlink.LinkSetUp(link); err != nil {
+			return err
+		}
+
+		route := &netlink.Route{
+			Scope:     netlink.SCOPE_UNIVERSE,
+			LinkIndex: link.Attrs().Index,
+			Gw:        net.ParseIP("172.29.0.1"),
+		}
+
+		return netlink.RouteAdd(route)
+	}
+
+	return netnsExecer.Exec(netnsFile, apply)
+}
+
+// WaitForInterface will block until the veth for the corresponding identifier is up. If the interface is not up
+//after a MaxWait then an error is returned
+func WaitForInterface(identifier string) error {
+	started := time.Now()
+
+	veth := "veth1_" + identifier
+	for {
+		_, err := net.InterfaceByName(veth)
+		if err == nil {
+			return nil
+		}
+
+		if time.Since(started) > WaitTimeout {
+			return ErrInterfaceTimedOut
+		}
+
+		time.Sleep(CheckInterval)

